<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan($root){$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){$p=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;else $files[$p]=$f->getSize();}ksort($files);$refs=[];$rx=["/\\b(?:require|require_once|include|include_once)\\s*\\(?\\s*['\"]([^'\"]+)['\"]/i","/\\b(?:import|export)\\s+(?:[^'\";]+?\\s+from\\s+)?['\"]([^'\"]+)['\"]/i","/\\b(?:src|href)\\s*=\\s*['\"]([^'\"]+)['\"]/i"];foreach($files as $p=>$size){if($size>700000||!preg_match('/\\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md)$/i',$p))continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;foreach($rx as $re){preg_match_all($re,$s,$m);foreach(array_unique($m[1]??[]) as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if(!$v||preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))continue;$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}}return['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan($ROOT);if(isset($_GET['pulse'])){header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s')]);exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationships</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#071016;color:#dce8ed;font-family:Inter,system-ui,sans-serif}.head{height:64px;border-bottom:1px solid #203139;padding:14px 20px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:700}.brand b{color:#55dfce}.stats{font:9px monospace;color:#70858d}.app{height:calc(100% - 64px);display:flex}.folders{width:260px;border-right:1px solid #203139;padding:16px;overflow:auto}.folders h4{margin:0 0 12px;color:#607780;font:8px monospace;letter-spacing:1px}.folder{padding:9px 10px;border-radius:6px;color:#9aaeb5;font:10px monospace;cursor:pointer}.folder:hover,.folder.active{background:#102128;color:#64ded2}.main{flex:1;position:relative;overflow:auto;padding:28px}.title{color:#607780;font:8px monospace;margin-bottom:14px}.files{display:flex;flex-wrap:wrap;gap:8px;align-content:flex-start}.file{border:1px solid #263d45;background:#0a151b;border-radius:6px;padding:8px 10px;color:#91a5ac;font:9px monospace;cursor:pointer}.file:hover,.file.active{border-color:#55dfce;color:#e9ffff}.empty{color:#526a73;font:10px monospace;padding:30px 0}.relation{position:fixed;right:20px;top:84px;width:300px;background:#09151bf5;border:1px solid #263d45;border-radius:8px;padding:14px;display:none}.relation.show{display:block}.relation button{float:right;background:none;border:0;color:#71858d;font-size:18px;cursor:pointer}.relation h3{margin:8px 0 2px;font-size:13px}.path{color:#55dfce;font:8px monospace;word-break:break-all}.list{margin-top:12px;font:8px monospace;color:#8da1a8;line-height:1.8;max-height:260px;overflow:auto}.wire{position:fixed;inset:64px 0 0 260px;pointer-events:none}.wire line{stroke:#477d80;stroke-width:1;stroke-dasharray:5 6}.wire circle{fill:#55dfce}.bottom{position:fixed;bottom:14px;left:276px;font:8px monospace;color:#566d76}.btn{border:1px solid #263d45;background:#09151b;color:#8fa6ad;border-radius:6px;padding:7px 10px;cursor:pointer}.search{width:100%;margin-bottom:12px;background:#09151b;border:1px solid #263d45;border-radius:6px;padding:9px;color:#fff;outline:0;font:9px monospace}@media(max-width:700px){.folders{width:180px;padding:10px}.main{padding:16px}.wire{left:180px}.bottom{left:196px}.relation{left:195px;right:10px;width:auto}.head{padding:12px}.stats{display:none}}
</style></head><body><header class="head"><div class="brand"><b>◇</b> SmartToolz Relationship Manager</div><div class="stats"><?php echo count($D['files']);?> files&nbsp; • &nbsp;<?php echo count($D['refs']);?> relations&nbsp; • &nbsp;<span style="color:#55dfce">LIVE</span></div></header><div class="app"><aside class="folders"><h4>FOLDERS</h4><input id="search" class="search" placeholder="Search…"><div id="folderList"></div></aside><main class="main"><div class="title" id="crumb">SELECT A FOLDER</div><div id="files" class="files"><div class="empty">Select a folder to see its files.</div></div></main></div><svg id="wire" class="wire"></svg><div id="relation" class="relation"><button id="close">×</button><div class="title">FILE RELATIONSHIPS</div><h3 id="rn"></h3><div id="rp" class="path"></div><div id="rl" class="list"></div></div><div class="bottom"><button class="btn" id="home">HOME</button> <button class="btn" id="refresh">RESCAN</button> <span id="hb">Server: <?php echo $D['time'];?></span></div>
<script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>;let current='',selected='';const $=id=>document.getElementById(id);function topFolders(){return[...new Set(D.files.map(f=>f.split('/')[0]))].sort()}function directFiles(folder){return D.files.filter(f=>f.startsWith(folder+'/')&&!f.slice(folder.length+1).includes('/'))}function drawFolders(filter=''){const list=$('folderList');list.innerHTML='';topFolders().filter(f=>f.toLowerCase().includes(filter.toLowerCase())).forEach(f=>{const b=document.createElement('div');b.className='folder'+(f===current?' active':'');b.textContent='📁 '+f;b.onclick=()=>openFolder(f);list.appendChild(b)})}function openFolder(f){current=f;selected='';$('crumb').textContent=f+' /';$('relation').classList.remove('show');const box=$('files');box.innerHTML='';const fs=directFiles(f);if(!fs.length){box.innerHTML='<div class="empty">No direct files in this folder.</div>'}fs.forEach(file=>{const b=document.createElement('button');b.className='file';b.textContent=file.split('/').pop();b.title=file;b.onclick=()=>selectFile(file,b);box.appendChild(b)});drawFolders($('search').value)}function selectFile(file,el){selected=file;document.querySelectorAll('.file').forEach(x=>x.classList.remove('active'));el.classList.add('active');const r=D.refs.filter(x=>x.from===file||x.to===file);$('rn').textContent=file.split('/').pop();$('rp').textContent=file;$('rl').innerHTML='<b>'+r.length+' direct relationships</b><br>'+r.map(x=>x.from+' → '+x.to).join('<br>')||'No direct relationships';$('relation').classList.add('show');drawWires(file)}function drawWires(file){const s=$('wire');s.innerHTML='';const refs=D.refs.filter(r=>r.from===file||r.to===file);if(!refs.length)return;const rect=document.querySelector('.file.active')?.getBoundingClientRect();if(!rect)return;refs.slice(0,20).forEach((r,i)=>{const line=document.createElementNS('http://www.w3.org/2000/svg','line');const x1=rect.right,y1=rect.top+rect.height/2,x2=window.innerWidth-330,y2=105+i*20;line.setAttribute('x1',x1);line.setAttribute('y1',y1);line.setAttribute('x2',x2);line.setAttribute('y2',y2);s.appendChild(line)})}$('search').oninput=e=>drawFolders(e.target.value);$('close').onclick=()=>{$('relation').classList.remove('show');selected='';document.querySelectorAll('.file').forEach(x=>x.classList.remove('active'));$('wire').innerHTML=''};$('home').onclick=()=>{current='';selected='';$('crumb').textContent='SELECT A FOLDER';$('files').innerHTML='<div class="empty">Select a folder to see its files.</div>';drawFolders()};$('refresh').onclick=()=>location.reload();drawFolders();setInterval(async()=>{try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'});const d=await r.json();$('hb').textContent='Server: '+d.time}catch(e){$('hb').textContent='Server: offline'}},2000);</script></body></html>